init_GitHubCopilotAuthService();
init_KiloAuthService();
init_i18n();
function copilotModelVendor(modelId) {
  if (/^claude/i.test(modelId)) return "Anthropic";
  if (/^gpt|^o[1-9]|^chatgpt|^codex/i.test(modelId)) return "OpenAI";
  if (/^gemini/i.test(modelId)) return "Google";
  if (/^mistral/i.test(modelId)) return "Mistral";
  return "Other";
}
function recommendedMaxTokens(modelId) {
  const bare = modelId.includes("/") ? modelId.split("/").pop() : modelId;
  const EXACT = {
    "claude-opus-4-6": 32e3,
    "claude-sonnet-4-5": 16384,
    "claude-sonnet-4": 16384,
    "claude-haiku-4-5-20251001": 8192,
    "claude-3-7-sonnet-20250219": 16384,
    "claude-3-5-sonnet-20241022": 8192,
    "claude-3.5-sonnet": 8192,
    "claude-3-5-haiku-20241022": 8192,
    "gpt-5": 32768,
    "gpt-5-mini": 16384,
    "gpt-5.4": 16384,
    "gpt-4.1": 32768,
    "gpt-4.1-mini": 16384,
    "gpt-4.1-nano": 16384,
    "gpt-4o": 16384,
    "gpt-4o-mini": 16384,
    "o3": 1e5,
    "o3-mini": 65536,
    "o4-mini": 1e5,
    "o1": 32768,
    "codex-mini-latest": 16384,
    "gemini-2.0-flash": 8192,
    "mistral-large-latest": 8192
  };
  if (EXACT[bare]) return EXACT[bare];
  if (/^claude-opus/i.test(bare)) return 32e3;
  if (/^claude-sonnet-4/i.test(bare)) return 16384;
  if (/^claude/i.test(bare)) return 8192;
  if (/^o[1-9]/i.test(bare)) return 1e5;
  if (/^gpt-5/i.test(bare)) return 32768;
  if (/^gpt-4/i.test(bare)) return 16384;
  return 8192;
}
