// src/ui/settings/ContentEditorModal.ts
var import_obsidian29 = require("obsidian");
init_i18n();
var ContentEditorModal = class extends import_obsidian29.Modal {
  initialContent;
  onSave;
  modalTitle;
  constructor(app, title, initialContent, onSave) {
    super(app);
    this.modalTitle = title;
    this.initialContent = initialContent;
    this.onSave = onSave;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.addClass("content-editor-modal");
    contentEl.createEl("h3", { cls: "content-editor-title", text: this.modalTitle });
    const textarea = contentEl.createEl("textarea", { cls: "content-editor-textarea" });
    textarea.value = this.initialContent;
    textarea.setAttribute("rows", "20");
    textarea.setAttribute("spellcheck", "false");
    const btnRow = contentEl.createDiv({ cls: "content-editor-btn-row" });
    const saveBtn = btnRow.createEl("button", { text: t("modal.modelConfig.save"), cls: "mod-cta" });
    const cancelBtn = btnRow.createEl("button", { text: t("modal.modelConfig.cancel") });
    saveBtn.addEventListener("click", () => {
      const result = this.onSave(textarea.value);
      if (result instanceof Promise) void result.catch(console.error);
      this.close();
    });
    cancelBtn.addEventListener("click", () => this.close());
    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(textarea.value.length, textarea.value.length);
    }, 50);
  }
  onClose() {
    this.contentEl.empty();
  }
};

// src/core/context/RulesLoader.ts
var RulesLoader = class {
  fs;
  rulesDir;
  constructor(fs8) {
    this.fs = fs8;
    this.rulesDir = "rules";
  }
  /**
   * Ensure the rules directory exists (create if needed).
   */
  async initialize() {
    try {
      const exists = await this.fs.exists(this.rulesDir);
      if (!exists) {
        await this.fs.mkdir(this.rulesDir);
      }
    } catch {
    }
  }
  /**
   * Discover all rule files in the rules directory.
   * Returns paths relative to the FileAdapter root (e.g. "rules/my-rule.md").
   */
  async discoverRules() {
    try {
      const exists = await this.fs.exists(this.rulesDir);
      if (!exists) return [];
      const listed = await this.fs.list(this.rulesDir);
      return listed.files.filter((f) => f.endsWith(".md") || f.endsWith(".txt")).sort();
    } catch {
      return [];
    }
  }
  /**
   * Load all enabled rule files into a combined string.
   * A rule is enabled if `toggles[path]` is not explicitly `false`.
   * (New rules default to enabled.)
   */
  async loadEnabledRules(toggles) {
    const paths = await this.discoverRules();
    const parts = [];
    for (const rPath of paths) {
      if (toggles[rPath] === false) continue;
      try {
        const content = await this.fs.read(rPath);
        if (content.trim()) {
          const limited = content.length > 5e4 ? content.slice(0, 5e4) : content;
          parts.push(limited.trim());
        }
      } catch {
      }
    }
    return parts.join("\n\n");
  }
  /**
   * Create a new rule file. Returns the path of the created file.
   */
  async createRule(name, content) {
    await this.initialize();
    const safeName = name.replace(/[^a-zA-Z0-9_ -]/g, "").trim() || "rule";
    const rPath = `${this.rulesDir}/${safeName}.md`;
    await this.fs.write(rPath, content);
    return rPath;
  }
  /**
   * Delete a rule file.
   */
  async deleteRule(rPath) {
    await this.fs.remove(rPath);
  }
  /**
   * Read a rule file's content (for UI editing).
   */
  readFile(rPath) {
    return this.fs.read(rPath);
  }
  /**
   * Write a rule file's content (for UI editing).
   */
  async writeFile(rPath, content) {
    await this.fs.write(rPath, content);
  }
  /**
   * Extract the display name from a rule path (filename without extension).
   */
  static displayName(rPath) {
    const parts = rPath.split("/");
    const filename = parts[parts.length - 1] ?? rPath;
    return filename.replace(/\.(md|txt)$/, "");
  }
};

