// src/core/tools/vault/ListFilesTool.ts
var ListFilesTool = class extends BaseTool {
  name = "list_files";
  isWriteOperation = false;
  constructor(plugin) {
    super(plugin);
  }
  getDefinition() {
    return {
      name: "list_files",
      description: 'List files and folders in a directory of the vault. Use recursive=true to list all files in nested subdirectories. Use path "/" or "" for the vault root.',
      input_schema: {
        type: "object",
        properties: {
          path: {
            type: "string",
            description: 'Directory path relative to vault root (e.g., "folder" or "/" for root)'
          },
          recursive: {
            type: "boolean",
            description: "If true, list files in all subdirectories as well"
          }
        },
        required: ["path"]
      }
    };
  }
  async execute(input, context) {
    const { callbacks } = context;
    const rawPath = input.path ?? "/";
    const recursive = input.recursive ?? false;
    try {
      const dirPath = rawPath === "/" || rawPath === "" ? "" : rawPath;
      const allFiles = this.app.vault.getFiles();
      const allFolders = this.app.vault.getAllFolders();
      const matchingFiles = allFiles.filter((f) => {
        if (!dirPath) return true;
        if (recursive) return f.path.startsWith(dirPath + "/") || f.path.startsWith(dirPath);
        const rel = dirPath ? f.path.replace(dirPath + "/", "") : f.path;
        return f.path.startsWith(dirPath ? dirPath + "/" : "") && !rel.includes("/");
      });
      const matchingFolders = allFolders.filter((folder) => {
        if (!dirPath) {
          return recursive ? folder.path !== "" : !folder.path.includes("/") && folder.path !== "";
        }
        if (recursive) return folder.path.startsWith(dirPath + "/");
        const rel = folder.path.replace(dirPath + "/", "");
        return folder.path.startsWith(dirPath + "/") && !rel.includes("/");
      });
      if (matchingFiles.length === 0 && matchingFolders.length === 0) {
        const target = this.app.vault.getAbstractFileByPath(dirPath);
        if (!target && dirPath !== "") {
          callbacks.pushToolResult(this.formatError(new Error(`Directory not found: ${rawPath}`)));
          return;
        }
        callbacks.pushToolResult(`(empty directory: ${rawPath})`);
        return;
      }
      const lines = [];
      for (const folder of matchingFolders.sort((a, b) => a.path.localeCompare(b.path))) {
        lines.push(`[DIR]  ${folder.path}/`);
      }
      for (const file of matchingFiles.sort((a, b) => a.path.localeCompare(b.path))) {
        lines.push(`[FILE] ${file.path}`);
      }
      const header = `Contents of "${rawPath || "/"}" (${matchingFolders.length} folders, ${matchingFiles.length} files${recursive ? ", recursive" : ""}):
`;
      callbacks.pushToolResult(header + lines.join("\n"));
      callbacks.log(`Listed ${lines.length} entries in ${rawPath}`);
    } catch (error2) {
      callbacks.pushToolResult(this.formatError(error2));
      await callbacks.handleError("list_files", error2);
    }
  }
};

// src/core/tools/vault/SearchFilesTool.ts
var MAX_RESULTS = 50;
var MAX_FILES_TO_SCAN = 500;
var SearchFilesTool = class extends BaseTool {
  name = "search_files";
  isWriteOperation = false;
  constructor(plugin) {
    super(plugin);
  }
  getDefinition() {
    return {
      name: "search_files",
      description: 'Search for a text pattern across files in the vault. Returns matching lines with file path and line numbers. Use path "/" to search the entire vault.',
      input_schema: {
        type: "object",
        properties: {
          path: {
            type: "string",
            description: 'Directory to search in (relative to vault root, or "/" for entire vault)'
          },
          pattern: {
            type: "string",
            description: "Text or regular expression to search for"
          },
          file_pattern: {
            type: "string",
            description: 'Optional file extension filter, e.g. ".md" or ".txt"'
          }
        },
        required: ["path", "pattern"]
      }
    };
  }
  async execute(input, context) {
    const { callbacks } = context;
    const rawPath = input.path ?? "/";
    const pattern = input.pattern ?? "";
    const filePattern = input.file_pattern;
    if (!pattern) {
      callbacks.pushToolResult(this.formatError(new Error("pattern parameter is required")));
      return;
    }
    try {
      const regex = safeRegex(pattern, "i");
      const dirPath = rawPath === "/" || rawPath === "" ? "" : rawPath;
      let files = this.app.vault.getFiles().filter((f) => {
        if (dirPath && !f.path.startsWith(dirPath + "/") && f.path !== dirPath) return false;
        if (filePattern && !f.name.endsWith(filePattern)) return false;
        return true;
      });
      if (files.length > MAX_FILES_TO_SCAN) {
        files = files.slice(0, MAX_FILES_TO_SCAN);
      }
      const results = [];
      let totalMatches = 0;
      for (const file of files) {
        if (totalMatches >= MAX_RESULTS) break;
        let content;
        try {
          content = await this.app.vault.cachedRead(file);
        } catch {
          continue;
        }
        const lines = content.split("\n");
        const fileMatches = [];
        for (let i = 0; i < lines.length; i++) {
          if (regex.test(lines[i])) {
            fileMatches.push(`  L${i + 1}: ${lines[i].trim()}`);
            totalMatches++;
            if (totalMatches >= MAX_RESULTS) break;
          }
        }
        if (fileMatches.length > 0) {
          results.push(`${file.path}:
${fileMatches.join("\n")}`);
        }
      }
      if (results.length === 0) {
        callbacks.pushToolResult(`No matches found for "${pattern}" in "${rawPath}".`);
        return;
      }
      const header = `Found ${totalMatches} match(es) for "${pattern}" in "${rawPath || "/"}":${totalMatches >= MAX_RESULTS ? ` (showing first ${MAX_RESULTS})` : ""}

`;
      callbacks.pushToolResult(header + results.join("\n\n"));
      callbacks.log(`Search "${pattern}" found ${totalMatches} matches across ${results.length} files`);
    } catch (error2) {
      callbacks.pushToolResult(this.formatError(error2));
      await callbacks.handleError("search_files", error2);
    }
  }
};

// src/core/tools/vault/WriteFileTool.ts
var import_obsidian51 = require("obsidian");
var WriteFileTool = class extends BaseTool {
  name = "write_file";
  isWriteOperation = true;
  // Triggers approval + checkpoint
  constructor(plugin) {
    super(plugin);
  }
  getDefinition() {
    return {
      name: "write_file",
      description: "Write content to a file in the vault, creating it if it does not exist. Use this to create new notes or completely replace existing content.",
      input_schema: {
        type: "object",
        properties: {
          path: {
            type: "string",
            description: 'Path to the file relative to vault root (e.g., "folder/note.md")'
          },
          content: {
            type: "string",
            description: "The complete content to write to the file"
          }
        },
        required: ["path", "content"]
      }
    };
  }
  async execute(input, context) {
    const { path: path8, content } = input;
    const { callbacks } = context;
    try {
      if (!path8) {
        throw new Error("Path parameter is required");
      }
      if (content === void 0 || content === null) {
        throw new Error("Content parameter is required");
      }
      const cfgDir = this.app.vault.configDir;
      if (path8.startsWith(`${cfgDir}/`) || path8.startsWith(".obsidian-agent/")) {
        await this.writeViaAdapter(path8, content, callbacks);
        return;
      }
      const existingFile = this.app.vault.getAbstractFileByPath(path8);
      if (existingFile) {
        if (!(existingFile instanceof import_obsidian51.TFile)) {
          throw new Error(`Path exists but is not a file: ${path8}`);
        }
        const existingContent = await this.app.vault.read(existingFile);
        await this.app.vault.modify(existingFile, content);
        const beforeLines = existingContent.split("\n").length;
        const afterLines = content.split("\n").length;
        const added = Math.max(0, afterLines - beforeLines);
        const removed = Math.max(0, beforeLines - afterLines);
        callbacks.pushToolResult(
          this.formatSuccess(`File updated: ${path8} (${content.length} chars)`) + `
<diff_stats added="${added}" removed="${removed}"/>`
        );
        callbacks.log(`Successfully updated file: ${path8}`);
      } else {
        const parentPath = path8.substring(0, path8.lastIndexOf("/"));
        if (parentPath) {
          await this.ensureFolderExists(parentPath);
        }
        await this.app.vault.create(path8, content);
        const newLines = content.split("\n").length;
        callbacks.pushToolResult(
          this.formatSuccess(`File created: ${path8} (${content.length} chars)`) + `
<diff_stats added="${newLines}" removed="0"/>`
        );
        callbacks.log(`Successfully created file: ${path8}`);
      }
    } catch (error2) {
      callbacks.pushToolResult(this.formatError(error2));
      await callbacks.handleError("write_file", error2);
    }
  }
  /**
   * Write via vault.adapter for paths outside the vault index (.obsidian/, .obsidian-agent/).
   * These paths are not tracked by Obsidian's file index, so vault.getAbstractFileByPath()
   * and vault.createFolder() don't work reliably for them.
   */
  async writeViaAdapter(path8, content, callbacks) {
    const adapter = this.app.vault.adapter;
    const existed = await adapter.exists(path8);
    const parentPath = path8.substring(0, path8.lastIndexOf("/"));
    if (parentPath) {
      const parentExists = await adapter.exists(parentPath);
      if (!parentExists) {
        await adapter.mkdir(parentPath);
      }
    }
    await adapter.write(path8, content);
    if (existed) {
      callbacks.pushToolResult(this.formatSuccess(`File updated: ${path8} (${content.length} chars)`));
      callbacks.log(`Successfully updated file: ${path8}`);
    } else {
      callbacks.pushToolResult(this.formatSuccess(`File created: ${path8} (${content.length} chars)`));
      callbacks.log(`Successfully created file: ${path8}`);
    }
  }
  /**
   * Ensure a folder path exists, creating it if needed
   */
  async ensureFolderExists(folderPath) {
    const folder = this.app.vault.getAbstractFileByPath(folderPath);
    if (!folder) {
      await this.app.vault.createFolder(folderPath);
    } else if (!(folder instanceof import_obsidian51.TFolder)) {
      throw new Error(`Path exists but is not a folder: ${folderPath}`);
    }
  }
};

