var import_obsidian52 = require("obsidian");
var EditFileTool = class extends BaseTool {
  name = "edit_file";
  isWriteOperation = true;
  constructor(plugin) {
    super(plugin);
  }
  getDefinition() {
    return {
      name: "edit_file",
      description: "Edit a file by replacing a specific string with a new string. Use this to make targeted edits to existing notes without replacing the entire content. The old_str must exactly match the content in the file (including whitespace and newlines). For multi-line replacements, include enough surrounding context in old_str to make it unique. If you need to append content, use append_to_file instead. If you need to create a new file or replace all content, use write_file instead.",
      input_schema: {
        type: "object",
        properties: {
          path: {
            type: "string",
            description: 'Path to the file relative to vault root (e.g., "folder/note.md")'
          },
          old_str: {
            type: "string",
            description: "The exact string to find in the file. Must be unique within the file. Include surrounding context if the string might appear multiple times."
          },
          new_str: {
            type: "string",
            description: "The string to replace old_str with. Can be empty string to delete old_str."
          },
          expected_replacements: {
            type: "number",
            description: "Number of replacements expected (default: 1). Set to a higher number only if old_str intentionally appears multiple times."
          }
        },
        required: ["path", "old_str", "new_str"]
      }
    };
  }
  async execute(input, context) {
    const { path: path8, old_str, new_str, expected_replacements = 1 } = input;
    const { callbacks } = context;
    try {
      if (!path8) throw new Error("path parameter is required");
      if (old_str === void 0 || old_str === null) throw new Error("old_str parameter is required");
      if (new_str === void 0 || new_str === null) throw new Error("new_str parameter is required");
      const file = this.app.vault.getAbstractFileByPath(path8);
      if (!file) throw new Error(`File not found: ${path8}`);
      if (!(file instanceof import_obsidian52.TFile)) throw new Error(`Path is not a file: ${path8}`);
      const content = await this.app.vault.read(file);
      const occurrences = this.countOccurrences(content, old_str);
      if (occurrences === 0) {
        const normalized = this.tryNormalizedMatch(content, old_str, new_str);
        if (normalized !== null) {
          await this.app.vault.modify(file, normalized);
          const stats2 = this.diffStats(content, normalized);
          const { added: added2, removed: removed2 } = this.diffNums(content, normalized);
          callbacks.pushToolResult(
            this.formatSuccess(`Edited ${path8} (fuzzy match applied): ${stats2}`) + `
<diff_stats added="${added2}" removed="${removed2}"/>`
          );
          return;
        }
        throw new Error(
          `old_str not found in file "${path8}". Make sure old_str exactly matches the file content including whitespace and newlines.`
        );
      }
      if (occurrences > expected_replacements) {
        throw new Error(
          `old_str appears ${occurrences} times in "${path8}" but expected_replacements is ${expected_replacements}. Add more surrounding context to old_str to make it unique, or increase expected_replacements.`
        );
      }
      const newContent = this.replaceFirst(content, old_str, new_str, expected_replacements);
      await this.app.vault.modify(file, newContent);
      const stats = this.diffStats(content, newContent);
      const replWord = expected_replacements === 1 ? "replacement" : "replacements";
      const { added, removed } = this.diffNums(content, newContent);
      callbacks.pushToolResult(
        this.formatSuccess(`Edited ${path8} (${expected_replacements} ${replWord}): ${stats}`) + `
<diff_stats added="${added}" removed="${removed}"/>`
      );
      callbacks.log(`Successfully edited file: ${path8}`);
    } catch (error2) {
      callbacks.pushToolResult(this.formatError(error2));
      await callbacks.handleError("edit_file", error2);
    }
  }
  /**
   * Count how many times needle appears in haystack (non-overlapping)
   */
  countOccurrences(haystack, needle) {
    if (!needle) return 0;
    let count2 = 0;
    let pos = 0;
    while ((pos = haystack.indexOf(needle, pos)) !== -1) {
      count2++;
      pos += needle.length;
    }
    return count2;
  }
  /**
   * Replace the first N occurrences of old_str with new_str
   */
  replaceFirst(content, oldStr, newStr, count2) {
    let result = content;
    let replaced = 0;
    let searchFrom = 0;
    while (replaced < count2) {
      const idx = result.indexOf(oldStr, searchFrom);
      if (idx === -1) break;
      result = result.substring(0, idx) + newStr + result.substring(idx + oldStr.length);
      searchFrom = idx + newStr.length;
      replaced++;
    }
    return result;
  }
  /**
   * Fallback: try matching after normalizing whitespace differences
   * Returns the modified content if match found, null otherwise.
   */
  tryNormalizedMatch(content, oldStr, newStr) {
    const normalize = (s) => s.replace(/[ \t]+/g, " ").replace(/\r\n/g, "\n").trim();
    const normContent = normalize(content);
    const normOld = normalize(oldStr);
    if (normContent.includes(normOld)) {
      const normNew = normalize(newStr);
      const replaced = normContent.replace(normOld, normNew);
      return replaced;
    }
    return null;
  }
  /**
   * Generate +N/-N diff stats string
   */
  diffStats(before, after) {
    const beforeLines = before.split("\n").length;
    const afterLines = after.split("\n").length;
    const diff2 = afterLines - beforeLines;
    if (diff2 > 0) return `+${diff2} lines`;
    if (diff2 < 0) return `${diff2} lines`;
    return "same line count";
  }
  /**
   * Return numeric added/removed line counts for diff badge
   */
  diffNums(before, after) {
    const beforeLines = before.split("\n").length;
    const afterLines = after.split("\n").length;
    return {
      added: Math.max(0, afterLines - beforeLines),
      removed: Math.max(0, beforeLines - afterLines)
    };
  }
};

