// src/core/tools/agent/UpdateTodoListTool.ts
var UpdateTodoListTool = class extends BaseTool {
  name = "update_todo_list";
  isWriteOperation = false;
  constructor(plugin) {
    super(plugin);
  }
  getDefinition() {
    return {
      name: "update_todo_list",
      description: "Publish your task plan as a visible checklist in the chat. ONLY use this for complex tasks that require 3 or more distinct steps. For simple tasks (answering a question, reading a file, making a single edit, or any task you can complete in one or two tool calls), execute directly WITHOUT creating a plan first. Format: one item per line using - [ ] (pending), - [~] (in progress), - [x] (done). Update after each step completes.",
      input_schema: {
        type: "object",
        properties: {
          todos: {
            type: "string",
            description: 'Markdown checklist. Each line must start with "- [ ]", "- [~]", or "- [x]". Example:\n- [x] Read existing notes\n- [~] Create summary\n- [ ] Add tags'
          }
        },
        required: ["todos"]
      }
    };
  }
  execute(input, context) {
    const { todos } = input;
    const { callbacks } = context;
    if (!todos || typeof todos !== "string") {
      callbacks.pushToolResult(this.formatError(new Error("todos parameter is required")));
      return Promise.resolve();
    }
    const items = this.parseTodos(todos);
    if (items.length === 0) {
      callbacks.pushToolResult(
        this.formatError(new Error("No valid todo items found. Use - [ ], - [~], or - [x] format."))
      );
      return Promise.resolve();
    }
    if (context.updateTodos) {
      context.updateTodos(items);
    }
    const done = items.filter((i) => i.status === "done").length;
    const total = items.length;
    callbacks.pushToolResult(
      `<todo_update items="${total}" done="${done}">Todo list updated (${done}/${total} complete)</todo_update>`
    );
    callbacks.log(`Todo list updated: ${done}/${total} done`);
    return Promise.resolve();
  }
  parseTodos(markdown) {
    return markdown.split("\n").map((line) => line.trim()).filter((line) => line.startsWith("- [")).map((line) => {
      const match = line.match(/^- \[([x~\s])\]\s*(.+)$/i);
      if (!match) return null;
      const statusChar = match[1].toLowerCase();
      const text = match[2].trim();
      const status = statusChar === "x" ? "done" : statusChar === "~" ? "in_progress" : "pending";
      return { text, status };
    }).filter((item) => item !== null);
  }
};

// src/core/tools/agent/SwitchModeTool.ts
var SwitchModeTool = class extends BaseTool {
  name = "switch_mode";
  isWriteOperation = false;
  constructor(plugin) {
    super(plugin);
  }
  getDefinition() {
    const allModes = [
      ...BUILT_IN_MODES,
      ...this.plugin.settings.customModes
    ];
    const modeList = allModes.map((m) => `- ${m.slug}: ${m.description}`).join("\n");
    return {
      name: "switch_mode",
      description: "Switch to a different agent mode when the current task is better handled by another mode. The new mode takes effect from the next response. Available modes:\n" + modeList,
      input_schema: {
        type: "object",
        properties: {
          mode_slug: {
            type: "string",
            description: 'The slug of the mode to switch to (e.g. "researcher", "writer", "architect").'
          },
          reason: {
            type: "string",
            description: "Brief explanation of why you are switching modes."
          }
        },
        required: ["mode_slug", "reason"]
      }
    };
  }
  execute(input, context) {
    const { mode_slug, reason } = input;
    const { callbacks } = context;
    if (!mode_slug) {
      callbacks.pushToolResult(this.formatError(new Error("mode_slug parameter is required")));
      return Promise.resolve();
    }
    const allModes = [...BUILT_IN_MODES, ...this.plugin.settings.customModes];
    const targetMode = allModes.find((m) => m.slug === mode_slug);
    if (!targetMode) {
      const available = allModes.map((m) => m.slug).join(", ");
      callbacks.pushToolResult(
        this.formatError(new Error(`Unknown mode: "${mode_slug}". Available: ${available}`))
      );
      return Promise.resolve();
    }
    if (context.switchMode) {
      context.switchMode(mode_slug);
    }
    callbacks.pushToolResult(
      `<mode_switch from="${this.plugin.settings.currentMode}" to="${mode_slug}">Switching to ${targetMode.name} mode. Reason: ${reason}</mode_switch>`
    );
    callbacks.log(`Mode switched to: ${mode_slug} \u2014 ${reason}`);
    return Promise.resolve();
  }
};

