var UI_ONLY_PATTERNS = [
  /^toggle/i,
  /toggle$/i,
  /^show-/i,
  /^focus/i,
  /settings$/i,
  /-panel$/i,
  /-sidebar$/i,
  /-pane$/i,
  /^open-settings/i,
  /^show-settings/i
];
function isUIOnlyCommand(commandName) {
  const lower = commandName.toLowerCase();
  return UI_ONLY_PATTERNS.some((p) => p.test(lower));
}
