// src/core/mastery/RecipeStore.ts
var RecipeStore = class {
  staticRecipes;
  learnedRecipes = [];
  memoryDB;
  fs;
  recipesDir;
  getLearnedEnabled;
  constructor(fs8, getLearnedEnabled, memoryDB) {
    this.fs = fs8;
    this.memoryDB = memoryDB ?? null;
    this.recipesDir = "recipes";
    this.staticRecipes = STATIC_RECIPES;
    this.getLearnedEnabled = getLearnedEnabled ?? (() => true);
  }
  /**
   * Load learned recipes from DB (or legacy JSON files).
   * Performs one-time migration from JSON -> DB if needed.
   */
  async initialize() {
    try {
      if (this.memoryDB?.isOpen()) {
        this.loadFromDB();
        if (this.learnedRecipes.length === 0) {
          await this.migrateFromFiles();
        }
      } else {
        await this.loadFromFiles();
      }
    } catch (e) {
      console.warn("[RecipeStore] Failed to initialize:", e);
    }
  }
  /** Get all recipes (static + learned), optionally filtered by mode. */
  getAll(mode) {
    const base = this.getLearnedEnabled() ? [...this.staticRecipes, ...this.learnedRecipes] : [...this.staticRecipes];
    if (!mode) return base;
    return base.filter((r) => r.modes.length === 0 || r.modes.includes(mode));
  }
  /** Get a recipe by ID. */
  getById(id) {
    return this.staticRecipes.find((r) => r.id === id) ?? this.learnedRecipes.find((r) => r.id === id);
  }
  /** Save a learned recipe. */
  async save(recipe) {
    recipe.source = "learned";
    recipe.schemaVersion = SCHEMA_VERSION2;
    if (this.memoryDB?.isOpen()) {
      this.saveToDB(recipe);
    } else {
      await this.saveToFile(recipe);
    }
    const idx = this.learnedRecipes.findIndex((r) => r.id === recipe.id);
    if (idx >= 0) {
      this.learnedRecipes[idx] = recipe;
    } else {
      this.learnedRecipes.push(recipe);
    }
  }
  /** Delete a learned recipe. */
  async delete(id) {
    const idx = this.learnedRecipes.findIndex((r) => r.id === id);
    if (idx >= 0) this.learnedRecipes.splice(idx, 1);
    if (this.memoryDB?.isOpen()) {
      this.memoryDB.getDB().run("DELETE FROM recipes WHERE id = ?", [id]);
      this.memoryDB.markDirty();
    } else {
      const filePath = `${this.recipesDir}/${id}.json`;
      const exists = await this.fs.exists(filePath);
      if (exists) await this.fs.remove(filePath);
    }
  }
  /** Increment success count and update lastUsed. */
  incrementSuccess(id) {
    const recipe = this.getById(id);
    if (recipe) {
      recipe.successCount++;
      recipe.lastUsed = (/* @__PURE__ */ new Date()).toISOString();
      if (recipe.source === "learned") {
        this.save(recipe).catch(
          (e) => console.warn(`[RecipeStore] Failed to persist success count for ${id}:`, e)
        );
      }
    }
  }
  // -----------------------------------------------------------------------
  // DB operations
  // -----------------------------------------------------------------------
  loadFromDB() {
    const db = this.memoryDB.getDB();
    const result = db.exec("SELECT id, name, description, trigger_keywords, steps, source, schema_version, success_count, last_used, modes FROM recipes WHERE source = ?", ["learned"]);
    if (result.length === 0) {
      this.learnedRecipes = [];
      return;
    }
    this.learnedRecipes = result[0].values.map((row) => {
      try {
        return {
          id: row[0],
          name: row[1],
          description: row[2] ?? "",
          trigger: row[3] ?? "",
          steps: JSON.parse(row[4] ?? "[]"),
          source: row[5],
          schemaVersion: row[6],
          successCount: row[7] ?? 0,
          lastUsed: row[8],
          modes: JSON.parse(row[9] ?? "[]")
        };
      } catch {
        return null;
      }
    }).filter((r) => r !== null && r.schemaVersion === SCHEMA_VERSION2);
  }
  saveToDB(recipe) {
    const db = this.memoryDB.getDB();
    db.run(
      `INSERT OR REPLACE INTO recipes (id, name, description, trigger_keywords, steps, source, schema_version, success_count, last_used, modes)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        recipe.id,
        recipe.name,
        recipe.description ?? "",
        recipe.trigger ?? "",
        JSON.stringify(recipe.steps),
        recipe.source,
        recipe.schemaVersion,
        recipe.successCount,
        recipe.lastUsed,
        JSON.stringify(recipe.modes)
      ]
    );
    this.memoryDB.markDirty();
  }
  // -----------------------------------------------------------------------
  // Legacy file operations (fallback + migration)
  // -----------------------------------------------------------------------
  async loadFromFiles() {
    const exists = await this.fs.exists(this.recipesDir);
    if (!exists) return;
    const files = await this.fs.list(this.recipesDir);
    const jsonFiles = files.files.filter((f) => f.endsWith(".json"));
    this.learnedRecipes = [];
    for (const file of jsonFiles) {
      try {
        const raw = await this.fs.read(file);
        const recipe = JSON.parse(raw);
        if (recipe.schemaVersion === SCHEMA_VERSION2 && recipe.source === "learned") {
          this.learnedRecipes.push(recipe);
        }
      } catch (e) {
        console.warn(`[RecipeStore] Failed to load recipe ${file}:`, e);
      }
    }
  }
  async saveToFile(recipe) {
    const exists = await this.fs.exists(this.recipesDir);
    if (!exists) await this.fs.mkdir(this.recipesDir);
    const filePath = `${this.recipesDir}/${recipe.id}.json`;
    await this.fs.write(filePath, JSON.stringify(recipe, null, 2));
  }
  /** One-time migration: import existing JSON recipe files into DB. */
  async migrateFromFiles() {
    try {
      const exists = await this.fs.exists(this.recipesDir);
      if (!exists) return;
      const files = await this.fs.list(this.recipesDir);
      const jsonFiles = files.files.filter((f) => f.endsWith(".json"));
      if (jsonFiles.length === 0) return;
      let migrated = 0;
      for (const file of jsonFiles) {
        try {
          const raw = await this.fs.read(file);
          const recipe = JSON.parse(raw);
          if (recipe.schemaVersion === SCHEMA_VERSION2 && recipe.source === "learned") {
            this.saveToDB(recipe);
            this.learnedRecipes.push(recipe);
            migrated++;
          }
        } catch {
        }
      }
      if (migrated > 0) {
        await this.memoryDB.save();
        console.debug(`[RecipeStore] Migrated ${migrated} recipes from JSON files to DB`);
      }
    } catch (e) {
      console.warn("[RecipeStore] Migration from files failed (non-fatal):", e);
    }
  }
};

// src/core/mastery/RecipeMatchingService.ts
var MAX_RESULTS2 = 3;
var MAX_CHARS = 2e3;
var MIN_TRIGGER_RECALL = 0.1;
var MIN_PREFIX_LEN = 6;
var RecipeMatchingService = class {
  store;
  constructor(store) {
    this.store = store;
  }
  /**
   * Find matching recipes for a user message.
   * Returns up to MAX_RESULTS recipes within the char budget.
   */
  match(userMessage, mode) {
    const recipes = this.store.getAll(mode);
    if (recipes.length === 0) return [];
    const msgTokens = this.tokenize(userMessage);
    if (msgTokens.size === 0) return [];
    const scored = [];
    for (const recipe of recipes) {
      const triggerTokens = this.tokenize(recipe.trigger.replace(/\|/g, " "));
      const score = this.triggerRecall(msgTokens, triggerTokens);
      if (score >= MIN_TRIGGER_RECALL) {
        scored.push({ recipe, score });
      }
    }
    scored.sort((a, b) => b.score - a.score);
    const topMatches = scored.slice(0, MAX_RESULTS2);
    return this.enforceCharBudget(topMatches);
  }
  /**
   * Build the prompt section string for matched recipes.
   * Returns empty string if no matches.
   */
  buildPromptSection(matches) {
    if (matches.length === 0) return "";
    const parts = [
      "====",
      "",
      "PROCEDURAL RECIPES",
      "",
      "For the following task types, use this proven step-by-step approach:",
      ""
    ];
    for (const { recipe } of matches) {
      parts.push(`**${recipe.name}** (${recipe.source})`);
      parts.push(recipe.description);
      parts.push("Steps:");
      for (let i = 0; i < recipe.steps.length; i++) {
        const step = recipe.steps[i];
        const prefix = step.conditional ? `  ${i + 1}. [if needed] ` : `  ${i + 1}. `;
        parts.push(`${prefix}${step.tool} -- ${step.note}`);
      }
      parts.push("");
    }
    parts.push("These are GUIDELINES, not rigid scripts. Adapt parameters to the specific task.");
    return parts.join("\n");
  }
  /**
   * Tokenize a string into a set of lowercase words (3+ chars).
   */
  tokenize(text) {
    const words = text.toLowerCase().replace(/[^a-z0-9\u00e4\u00f6\u00fc\u00df]/g, " ").split(/\s+/).filter((w) => w.length >= 3);
    return new Set(words);
  }
  /**
   * Trigger recall: |matched trigger tokens| / |total trigger tokens|
   *
   * Unlike Jaccard, this is NOT penalized by long user messages.
   * A single specific keyword like "excalidraw" in a 20-word message
   * still produces a meaningful score (1/8 = 0.125).
   *
   * Also supports prefix matching for German word forms:
   * "visualisiert" matches "visualisierung" (shared prefix >= 6 chars).
   */
  triggerRecall(msgTokens, triggerTokens) {
    if (triggerTokens.size === 0) return 0;
    let matched = 0;
    const msgArray = [...msgTokens];
    for (const trigger of triggerTokens) {
      if (msgTokens.has(trigger)) {
        matched++;
        continue;
      }
      if (trigger.length >= MIN_PREFIX_LEN) {
        const prefix = trigger.slice(0, MIN_PREFIX_LEN);
        if (msgArray.some((m) => m.length >= MIN_PREFIX_LEN && m.startsWith(prefix))) {
          matched += 0.8;
        }
      }
    }
    return matched / triggerTokens.size;
  }
  /**
   * Trim results to fit within the character budget.
   */
  enforceCharBudget(matches) {
    const result = [];
    let totalChars = 0;
    for (const match of matches) {
      const recipeChars = this.estimateRecipeChars(match.recipe);
      if (totalChars + recipeChars > MAX_CHARS && result.length > 0) break;
      result.push(match);
      totalChars += recipeChars;
    }
    return result;
  }
  /**
   * Rough character estimate for a serialized recipe in the prompt.
   */
  estimateRecipeChars(recipe) {
    let chars2 = recipe.name.length + recipe.description.length + 50;
    for (const step of recipe.steps) {
      chars2 += step.tool.length + step.note.length + 20;
    }
    return chars2;
  }
};

